function catSvg(kind){const c='viewBox="0 0 220 130"';const bg='<rect width="220" height="130" rx="18" fill="#edf0f4"/>';
if(kind==='amr'||kind==='warehouse')return `<svg ${c}>${bg}<rect x="48" y="70" width="124" height="38" rx="14" fill="#58687b"/><circle cx="75" cy="109" r="9" fill="#202938"/><circle cx="148" cy="109" r="9" fill="#202938"/><rect x="88" y="50" width="44" height="22" rx="8" fill="#8fb4ff"/><circle cx="110" cy="43" r="8" fill="#2848ff"/></svg>`;
if(kind==='humanoid')return `<svg ${c}>${bg}<circle cx="110" cy="28" r="15" fill="#7b8ba0"/><rect x="94" y="45" width="32" height="42" rx="12" fill="#5f8cff"/><path d="M97 58 L70 82 M123 58 L151 82 M101 84 L87 116 M119 84 L134 116" stroke="#65758a" stroke-width="10" stroke-linecap="round"/></svg>`;
if(kind==='quadruped')return `<svg ${c}>${bg}<rect x="66" y="48" width="86" height="40" rx="14" fill="#5f8cff"/><rect x="145" y="52" width="30" height="22" rx="8" fill="#7fa4ff"/><path d="M78 84 L65 113 M99 84 L95 113 M130 84 L136 113 M148 82 L162 111" stroke="#526278" stroke-width="9" stroke-linecap="round"/></svg>`;
if(kind==='mobile')return `<svg ${c}>${bg}<rect x="52" y="84" width="116" height="30" rx="12" fill="#58687b"/><circle cx="78" cy="114" r="7" fill="#202938"/><circle cx="144" cy="114" r="7" fill="#202938"/><circle cx="112" cy="78" r="17" fill="#f6c83f"/><rect x="104" y="32" width="18" height="55" rx="9" fill="#efb31a" transform="rotate(-25 113 60)"/><rect x="111" y="28" width="56" height="14" rx="7" fill="#efb31a"/></svg>`;
if(kind==='cleanroom')return `<svg ${c}>${bg}<circle cx="72" cy="69" r="30" fill="#dce7ff" stroke="#7fa4ff" stroke-width="5"/><circle cx="72" cy="69" r="6" fill="#2848ff"/><rect x="116" y="34" width="17" height="61" rx="8" fill="#8290a3"/><rect x="126" y="34" width="54" height="14" rx="7" fill="#67778b"/></svg>`;
if(kind==='scara')return `<svg ${c}>${bg}<rect x="104" y="35" width="26" height="76" rx="8" fill="#9aa6b2"/><rect x="54" y="36" width="68" height="16" rx="8" fill="#687789"/><rect x="122" y="55" width="60" height="14" rx="7" fill="#687789"/><rect x="174" y="58" width="8" height="43" rx="4" fill="#202938"/></svg>`;
if(kind==='delta')return `<svg ${c}>${bg}<rect x="45" y="25" width="130" height="12" rx="6" fill="#707d8e"/><path d="M65 37 L99 89 M110 37 L110 89 M155 37 L121 89" stroke="#8491a3" stroke-width="6"/><circle cx="110" cy="94" r="13" fill="#202938"/></svg>`;
if(kind==='welding')return `<svg ${c}>${bg}<rect x="55" y="89" width="80" height="24" rx="8" fill="#f0b51c"/><rect x="88" y="40" width="18" height="63" rx="9" fill="#f0b51c" transform="rotate(-25 97 72)"/><rect x="92" y="32" width="78" height="16" rx="8" fill="#f0b51c"/><path d="M171 42 L195 77" stroke="#202938" stroke-width="8"/><path d="M194 76 l7 7 m-7-7 l-8 10 m8-10 l2 13" stroke="#ff7a00" stroke-width="3"/></svg>`;
if(kind==='painting')return `<svg ${c}>${bg}<rect x="54" y="88" width="72" height="25" rx="8" fill="#72a5ff"/><rect x="84" y="38" width="18" height="65" rx="9" fill="#72a5ff" transform="rotate(-26 93 70)"/><rect x="91" y="29" width="77" height="16" rx="8" fill="#72a5ff"/><circle cx="195" cy="55" r="4" fill="#2848ff"/><circle cx="203" cy="66" r="4" fill="#2848ff"/></svg>`;
if(kind==='pallet')return `<svg ${c}>${bg}<rect x="31" y="91" width="72" height="15" rx="4" fill="#a87336"/><rect x="35" y="70" width="28" height="20" fill="#d49a55"/><rect x="65" y="70" width="28" height="20" fill="#c88943"/><rect x="121" y="88" width="65" height="25" rx="8" fill="#f0b51c"/><rect x="141" y="32" width="17" height="67" rx="8" fill="#f0b51c" transform="rotate(25 150 66)"/></svg>`;
return `<svg ${c}>${bg}<rect x="60" y="91" width="82" height="24" rx="8" fill="#f0b51c"/><circle cx="102" cy="81" r="24" fill="#f6c83f"/><rect x="94" y="38" width="18" height="57" rx="9" fill="#f0b51c" transform="rotate(-25 103 67)"/><rect x="101" y="30" width="73" height="16" rx="8" fill="#f0b51c"/></svg>`}

const LANGUAGE_MARKET={ja:'Japan',ko:'Korea',zh:'China',de:'Germany',fr:'France',es:'Spain',it:'Italy',pt:'Brazil',vi:'Vietnam',en:''};
let currentLang='en';
function populateCompanyCountries(){const sel=document.getElementById('companyCountryFilter');if(!sel)return;const current=sel.value;const countries=[...new Set(companies.map(c=>c.country).filter(Boolean))].sort((a,b)=>a.localeCompare(b));sel.innerHTML=`<option value="">${tr('allCountries')}</option>`+countries.map(c=>`<option value="${esc(c)}">${esc(c)}</option>`).join('');if(countries.includes(current))sel.value=current;}
function applyPreferredCompanyMarket(lang,force=true){const sel=document.getElementById('companyCountryFilter');if(!sel)return;populateCompanyCountries();const target=LANGUAGE_MARKET[lang]||'';if(force)sel.value=[...sel.options].some(o=>o.value===target)?target:'';renderCompanies();}

function applyLang(lang){if(!T[lang])lang='en';currentLang=lang;document.documentElement.lang=lang;const t=T[lang];document.querySelectorAll('[data-i18n]').forEach(el=>{const k=el.dataset.i18n;el.textContent=t[k]??T.en[k]??el.textContent});document.querySelectorAll('[data-i18n-placeholder]').forEach(el=>{const k=el.dataset.i18nPlaceholder;el.placeholder=t[k]??T.en[k]??el.placeholder});document.querySelectorAll('[data-i18n-html]').forEach(el=>{const k=el.dataset.i18nHtml;el.innerHTML=t[k]??T.en[k]??el.innerHTML});localStorage.setItem('rqLangV19',lang);populateCompanyCountries();applyPreferredCompanyMarket(lang,true);renderCategories();renderListings();renderMakers();renderNetwork();renderPurchaseChannels();renderEvents();if(document.getElementById('searchPageInput')?.value)renderGlobalSearch(document.getElementById('searchPageInput').value)}
function route(id){document.querySelectorAll('.page').forEach(p=>p.classList.remove('active'));document.getElementById(id)?.classList.add('active');window.scrollTo(0,0)}
document.querySelectorAll('[data-route]').forEach(el=>el.addEventListener('click',e=>{e.preventDefault();route(el.dataset.route)}));
function yen(n){return n?new Intl.NumberFormat('ja-JP',{style:'currency',currency:'JPY',maximumFractionDigits:0}).format(n):tr('getOffers')}
function renderCategories(){const lang=document.documentElement.lang||'en';const card=(c,kind)=>`<article class="category-card" data-kind="${kind}" data-cat="${c.id}"><div class="category-visual">${catSvg(c.icon)}</div><div class="category-info"><h3>${c.names[lang]||c.names.en}</h3><p>${c.desc[lang]||c.desc.en}</p></div></article>`;document.getElementById('robotTypeGrid').innerHTML=robotTypes.map(c=>card(c,'type')).join('');document.getElementById('applicationGrid').innerHTML=applications.map(c=>card(c,'app')).join('');document.getElementById('homeCategoryStrip').innerHTML=robotTypes.slice(0,4).map(c=>card(c,'type')).join('');document.querySelectorAll('.category-card').forEach(el=>el.addEventListener('click',()=>{if(el.dataset.kind==='app')document.getElementById('applicationFilter').value=el.dataset.cat;else document.getElementById('categoryFilter').value=el.dataset.cat;route('robots');renderListings()}));const sf=document.getElementById('categoryFilter');sf.innerHTML=`<option value="">${tr('allCategories')}</option>`+robotTypes.map(c=>`<option value="${c.id}">${c.names[lang]||c.names.en}</option>`).join('');const af=document.getElementById('applicationFilter');af.innerHTML=`<option value="">${tr('allApplications')}</option>`+applications.map(c=>`<option value="${c.id}">${c.names[lang]||c.names.en}</option>`).join('');renderMakerTypeFilter()}
function listingCard(r){const bid=r.sale==='bid';return `<article class="listing-card"><div class="listing-photo"><span class="country-badge">${r.country}</span><span class="listing-badge">${bid?tr('bidding'):tr('fixedPrice')}</span><div class="mini-robot"></div></div><div class="listing-body"><h3>${r.brand} ${r.model}</h3><div class="listing-meta">${r.year} · ${r.payload} · ${r.location}</div><div class="listing-price"><strong>${yen(r.price)}</strong><span class="verified">${r.verified?'✓ VERIFIED':tr('directory')}</span></div><div class="listing-actions"><button class="card-btn" onclick="openAuth('inquiry','${r.brand} ${r.model}')">${tr('askSeller')}</button><button class="card-btn main" onclick="openAuth('${bid?'bid':'buy'}','${r.brand} ${r.model}')">${bid?tr('placeBid'):tr('buyContact')}</button></div></div></article>`}
function renderListings(){const q=(document.getElementById('marketSearch')?.value||'').toLowerCase();const cat=document.getElementById('categoryFilter')?.value||'';const app=document.getElementById('applicationFilter')?.value||'';const country=document.getElementById('countryFilter')?.value||'';const sale=document.getElementById('saleFilter')?.value||'';let all=[...listings,...JSON.parse(localStorage.getItem('rqListings')||'[]')];let filtered=all.filter(r=>(!q||`${r.brand} ${r.model} ${r.location}`.toLowerCase().includes(q))&&(!cat||r.cat===cat)&&(!app||(r.apps||[]).includes(app))&&(!country||r.country===country)&&(!sale||r.sale===sale));document.getElementById('marketListings').innerHTML=filtered.map(listingCard).join('')||'<p>No results.</p>';document.getElementById('homeListings').innerHTML=all.slice(0,3).map(listingCard).join('')}
['marketSearch','categoryFilter','applicationFilter','countryFilter','saleFilter'].forEach(id=>document.getElementById(id)?.addEventListener('input',renderListings));
function renderPurchaseChannels(){const box=document.getElementById('retailerGrid');if(!box)return;const q=(document.getElementById('buySearch')?.value||'').toLowerCase();const country=document.getElementById('buyCountry')?.value||'';const maker=document.getElementById('buyMaker')?.value||'';const mode=document.getElementById('buyMode')?.value||'';const list=purchaseChannels.filter(x=>(!q||`${x.retailer} ${x.maker} ${x.product}`.toLowerCase().includes(q))&&(!country||x.country===country)&&(!maker||x.maker===maker)&&(!mode||x.mode===mode));box.innerHTML=list.map(x=>`<article class="retailer-card"><div class="retailer-top"><span class="retailer-status ${x.status==='Official'?'official':''}">${x.status==='Official'?tr('official'):tr('retailer')}</span><span>${x.country}</span></div><div class="retailer-brand">${x.maker}</div><h3>${x.product}</h3><p class="retailer-name">${x.retailer}</p><div class="retailer-data"><div><small>${tr('sourcePrice')}</small><strong>${x.price}</strong></div><div><small>${tr('availability')}</small><strong>${x.availability}</strong></div></div><p class="retailer-note">${x.note}</p><div class="checked-row"><span>✓ ${tr('lastChecked')}: ${x.checked}</span><a href="${x.url}" target="_blank" rel="noopener">${tr('checkLatest')} ↗</a></div><a class="store-button" href="${x.url}" target="_blank" rel="noopener">${tr('visitStore')} →</a></article>`).join('')||`<p>${tr('noBuyResults')}</p>`}
['buySearch','buyCountry','buyMaker','buyMode'].forEach(id=>document.getElementById(id)?.addEventListener('input',renderPurchaseChannels));
let makerTab='robot';
function renderMakerTypeFilter(){const lang=document.documentElement.lang||'en';const s=document.getElementById('makerTypeFilter');if(!s)return;s.innerHTML=`<option value="">${tr('allRobotTypes')}</option>`+robotTypes.map(c=>`<option value="${c.id}">${c.names[lang]||c.names.en}</option>`).join('')}

function eventStatus(e){const now=new Date();now.setHours(0,0,0,0);const end=new Date(e.end+'T23:59:59');return end>=now?'upcoming':'past'}
function fmtEventDate(e){const opt={year:'numeric',month:'short',day:'numeric'};const locale={ja:'ja-JP',ko:'ko-KR',zh:'zh-CN',de:'de-DE',fr:'fr-FR',es:'es-ES',it:'it-IT',pt:'pt-BR',vi:'vi-VN',en:'en-US'}[currentLang]||'en-US';const a=new Date(e.start+'T12:00:00').toLocaleDateString(locale,opt);const b=new Date(e.end+'T12:00:00').toLocaleDateString(locale,opt);return e.start===e.end?a:`${a} – ${b}`}
function renderEvents(){const country=document.getElementById('eventCountryFilter')?.value||'';const type=document.getElementById('eventTypeFilter')?.value||'';const phase=document.getElementById('eventPhaseFilter')?.value||'upcoming';let list=events.filter(e=>(!country||e.country===country)&&(!type||e.type===type)&&(!phase||eventStatus(e)===phase));list.sort((a,b)=>phase==='past'?b.start.localeCompare(a.start):a.start.localeCompare(b.start));const grid=document.getElementById('eventGrid');if(!grid)return;grid.innerHTML=list.map(e=>`<article class="event-card"><div class="event-date"><strong>${fmtEventDate(e)}</strong><span>${e.city} · ${e.country}</span></div><div class="event-top"><span>${e.type}</span><span class="event-confirmed">✓ ${tr('dateConfirmed')}</span></div><h3>${e.name}</h3><p>${e.venue}</p><div class="event-footer"><small>${tr('lastChecked')}: ${e.checked}</small><a class="card-link" href="${e.url}" target="_blank" rel="noopener">${tr('officialEventSite')} ↗</a></div></article>`).join('')||`<div class="search-empty"><h2>${tr('noSearchResults')}</h2></div>`;}
function populateEventFilters(){const c=document.getElementById('eventCountryFilter'),t=document.getElementById('eventTypeFilter');if(c){const countries=[...new Set(events.map(e=>e.country))].sort();c.innerHTML=`<option value="">${tr('eventCountry')}</option>`+countries.map(x=>`<option>${x}</option>`).join('')}if(t){const types=[...new Set(events.map(e=>e.type))].sort();t.innerHTML=`<option value="">${tr('allEventTypes')}</option>`+types.map(x=>`<option>${x}</option>`).join('')}}
function renderMakers(){const region=document.getElementById('makerRegionFilter')?.value||'';const type=document.getElementById('makerTypeFilter')?.value||'';let list=makers[makerTab]||[];if(makerTab==='robot')list=list.filter(m=>(!region||m.region===region)&&(!type||m.types.includes(type)));else list=list.filter(m=>(!region||m.region===region));document.getElementById('makerCount').textContent=`${list.length} ${tr('makerCountLabel')}`;document.getElementById('makerGrid').innerHTML=list.map(m=>`<article class="maker-card"><div class="maker-mark">${m.name}</div><div class="maker-origin">${m.origin} · ${m.region}</div><h3>${m.name}</h3><p>${m.series}</p><div class="tag-row">${m.types.slice(0,4).map(t=>`<span>${t}</span>`).join('')}</div><div class="maker-status">${m.status==='official-source'?`✓ ${tr('officialSource')}`:tr('directorySeed')}</div><button class="card-btn" onclick="showMaker('${m.name.replaceAll("'","\\'")}')">${tr('explore')}</button></article>`).join('')}
['makerRegionFilter','makerTypeFilter'].forEach(id=>document.getElementById(id)?.addEventListener('change',renderMakers));
document.querySelectorAll('[data-maker-tab]').forEach(b=>b.addEventListener('click',()=>{makerTab=b.dataset.makerTab;document.querySelectorAll('[data-maker-tab]').forEach(x=>x.classList.remove('active'));b.classList.add('active');document.getElementById('makerTypeFilter').disabled=makerTab==='eoat';renderMakers()}));
window.showMaker=function(name){const m=(makers.robot||[]).concat(makers.eoat||[]).find(x=>x.name===name);if(!m)return;openModal(`<div class="kicker">MANUFACTURER</div><h2>${m.name}</h2><p>${m.series}</p><div class="tag-row"><span>${m.origin}</span><span>${m.region}</span>${m.types.map(t=>`<span>${t}</span>`).join('')}</div><p>${m.status==='official-source'?tr('officialSource'):tr('directorySeed')}</p><p>${tr('dealerRule')}</p><div class="modal-actions"><button class="secondary" onclick="closeModal()">${tr('close')}</button><button class="primary" onclick="openAuth('maker','${m.name.replaceAll("'","\\'")}')">${tr('requestQuote')}</button></div>`)}
function renderNetwork(){const box=document.getElementById('networkGrid');if(!box)return;box.innerHTML=regionalNetwork.map(n=>`<article class="network-card"><div class="network-top"><strong>${n.country}</strong><span>${n.status}</span></div><h3>${n.name}</h3><p>${n.type} · ${n.region}</p><div class="tag-row">${n.makers.map(m=>`<span>${m}</span>`).join('')}</div><button class="card-btn main" onclick="openAuth('company','${n.name.replaceAll("'","\\'")}')">${tr('requestQuote')}</button></article>`).join('')}
function renderCompanies(){const q=(document.getElementById('companySearch')?.value||'').toLowerCase();const type=document.getElementById('companyTypeFilter')?.value||'';const country=document.getElementById('companyCountryFilter')?.value||'';const list=companies.filter(c=>(!q||`${c.name} ${c.type} ${c.country} ${c.region} ${(c.skills||[]).join(' ')}`.toLowerCase().includes(q))&&(!type||c.type===type)&&(!country||c.country===country));const count=document.getElementById('companyCount');if(count)count.textContent=`${list.length} ${tr('companyCount')}`;const note=document.getElementById('companyMarketNote');if(note)note.textContent=country?`${tr('localCompanies')}: ${country}`:tr('allGlobalCompanies');document.getElementById('companyGrid').innerHTML=list.map(c=>`<article class="company-card"><div class="company-top"><div class="company-logo">${c.name.split(' ').map(x=>x[0]).join('').slice(0,2)}</div><span class="status ${c.status==='Official source'?'verified':''}">${c.status==='Official source'?tr('officialSource'):(c.status||tr('directorySeed'))}</span></div><h3>${c.name}</h3><div class="company-type">${c.type} · ${c.region} · ${c.country}</div><div class="tag-row">${(c.skills||[]).slice(0,6).map(s=>`<span>${s}</span>`).join('')}</div><div class="company-contact"><button class="card-btn main" onclick="openAuth('company','${c.name.replaceAll("'","\\'")}')">${tr('contact')}</button>${c.source_url?`<a class="card-link" href="${c.source_url}" target="_blank" rel="noopener">${tr('openWebsite')} ↗</a>`:`<button class="card-btn" onclick="claimCompany('${c.name.replaceAll("'","\\'")}')">${tr('claimProfile')}</button>`}</div></article>`).join('')}
['companySearch','companyTypeFilter','companyCountryFilter'].forEach(id=>document.getElementById(id)?.addEventListener('input',renderCompanies));
function openModal(html){document.getElementById('modal').innerHTML=html;document.getElementById('modalBackdrop').classList.remove('hidden')}window.closeModal=()=>document.getElementById('modalBackdrop').classList.add('hidden');document.getElementById('modalBackdrop').addEventListener('click',e=>{if(e.target.id==='modalBackdrop')closeModal()});
window.openAuth=function(type,target){openModal(`<div class="kicker">ROBOQUO ACCESS</div><h2>${tr('authTitle')}</h2><p>${tr('authBody')}</p><label>${tr('email')}<input id="authEmail" type="email" placeholder="name@company.com"></label><div class="modal-actions"><button class="secondary" onclick="closeModal()">${tr('cancel')}</button><button class="primary" onclick="completeAuth('${type}','${target.replaceAll("'","\\'")}')">${tr('continue')}</button></div>`)}
window.completeAuth=function(type,target){const email=document.getElementById('authEmail').value.trim();if(!email||!email.includes('@')){toast(tr('emailRequired'));return}localStorage.setItem('rqUserEmail',email);if(type==='bid')openBid(target);else{closeModal();toast(`${target}: ${tr('requestStarted')}`)}}
function openBid(target){openModal(`<div class="kicker">BIDDING</div><h2>${target}</h2><p>${tr('bidBody')}</p><label>${tr('offerPrice')}<input id="bidPrice" type="number" value="1200000"></label><label>${tr('message')}<textarea id="bidMsg" rows="3"></textarea></label><div class="modal-actions"><button class="secondary" onclick="closeModal()">${tr('cancel')}</button><button class="primary" onclick="submitBid('${target.replaceAll("'","\\'")}')">${tr('submitBid')}</button></div>`)}
window.submitBid=function(target){const bids=JSON.parse(localStorage.getItem('rqBids')||'[]');bids.push({target,price:+document.getElementById('bidPrice').value,email:localStorage.getItem('rqUserEmail'),date:new Date().toISOString()});localStorage.setItem('rqBids',JSON.stringify(bids));closeModal();toast(tr('bidSubmitted'))}
function sellFlow(){const lang=document.documentElement.lang;openModal(`<div class="kicker">SELL WITH ROBOQUO</div><h2>${tr('sellModalTitle')}</h2><p>${tr('sellModalBody')}</p><div class="dropzone">📷<br><strong>${tr('photoGuide')}</strong><br><input type="file" multiple accept="image/*,video/*"></div><label>${tr('company')}<input id="sellCompany" placeholder="ABC Automation"></label><div class="form-grid"><label>${tr('maker')}<input id="sellBrand" value="FANUC"></label><label>${tr('model')}<input id="sellModel" value="M-20iA/20M"></label><label>${tr('year')}<input id="sellYear" type="number" value="2020"></label><label>${tr('country')}<select id="sellCountry"><option>Japan</option><option>Korea</option><option>Germany</option><option>USA</option></select></label></div><label>${tr('category')}<select id="sellCat">${robotTypes.map(c=>`<option value="${c.id}">${c.names[lang]||c.names.en}</option>`).join('')}</select></label><label>${tr('saleMethod')}<select id="sellSale"><option value="fixed">${tr('fixedPrice')}</option><option value="bid">${tr('getBids')}</option></select></label><label>${tr('priceJpy')}<input id="sellPrice" type="number" value="1200000"></label><div class="modal-actions"><button class="secondary" onclick="closeModal()">${tr('cancel')}</button><button class="primary" onclick="saveListing()">${tr('publishDemo')}</button></div>`)}
document.querySelectorAll('[data-action="sell"]').forEach(b=>b.addEventListener('click',sellFlow));
window.saveListing=function(){const arr=JSON.parse(localStorage.getItem('rqListings')||'[]');arr.unshift({id:Date.now(),brand:document.getElementById('sellBrand').value,model:document.getElementById('sellModel').value,year:+document.getElementById('sellYear').value,payload:'—',country:document.getElementById('sellCountry').value,location:document.getElementById('sellCountry').value,price:+document.getElementById('sellPrice').value,sale:document.getElementById('sellSale').value,cat:document.getElementById('sellCat').value,apps:[],verified:false});localStorage.setItem('rqListings',JSON.stringify(arr));closeModal();renderListings();route('robots');toast(tr('listingPublished'))}
