function esc(s){return String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]))}
function norm(s){return String(s??'').normalize('NFKD').replace(/[\u0300-\u036f]/g,'').toLowerCase()}
function matchQuery(parts,q){const hay=norm(parts.flat(Infinity).filter(Boolean).join(' '));return q.split(/\s+/).filter(Boolean).every(term=>hay.includes(term))}
function allRobotListings(){return [...listings,...JSON.parse(localStorage.getItem('rqListings')||'[]')]}
function resultGroup(title,items,routeId){if(!items.length)return '';return `<section class="search-group"><div class="search-group-head"><div><h2>${esc(title)}</h2><span>${items.length}</span></div>${routeId?`<button class="link-btn" onclick="route('${routeId}')">${esc(tr('viewSection'))} →</button>`:''}</div><div class="search-result-grid">${items.join('')}</div></section>`}
function renderGlobalSearch(raw){const input=document.getElementById('searchPageInput');if(input&&input.value!==raw)input.value=raw;const q=norm(raw.trim());const out=document.getElementById('globalSearchResults');const summary=document.getElementById('searchSummary');if(!q){summary.textContent=tr('searchHint');out.innerHTML='';return}
 const lang=document.documentElement.lang||'en';
 const robotHits=allRobotListings().filter(r=>matchQuery([r.brand,r.model,r.year,r.payload,r.country,r.location,r.cat,r.apps],q)).slice(0,12);
 const makerHits=[...(makers.robot||[]),...(makers.eoat||[])].filter(m=>matchQuery([m.name,m.origin,m.region,m.types,m.series],q)).slice(0,16);
 const companyPool=[...companies,...regionalNetwork.filter(n=>!companies.some(c=>c.name===n.name))];
 const companyHits=companyPool.filter(c=>matchQuery([c.name,c.type,c.country,c.region,c.skills||c.makers,c.status],q)).slice(0,16);
 const buyHits=purchaseChannels.filter(p=>matchQuery([p.retailer,p.maker,p.product,p.country,p.mode,p.price,p.availability,p.status],q)).slice(0,12);
 const categoryHits=[...robotTypes.map(c=>({...c,_kind:'type'})),...applications.map(c=>({...c,_kind:'app'}))].filter(c=>matchQuery([c.id,Object.values(c.names),Object.values(c.desc)],q)).slice(0,16);
 const total=robotHits.length+makerHits.length+companyHits.length+buyHits.length+categoryHits.length+eventHits.length;
 summary.innerHTML=`<strong>${esc(tr('searchResultsFor'))} “${esc(raw.trim())}”</strong><span>${total} ${esc(tr('searchFound'))}</span>`;
 const robotCards=robotHits.map(r=>`<article class="search-result-card"><div class="result-type">${esc(tr('searchRobots'))}</div><h3>${esc(r.brand)} ${esc(r.model)}</h3><p>${esc(r.year)} · ${esc(r.payload)} · ${esc(r.location)} · ${esc(r.country)}</p><div class="tag-row"><span>${esc(r.sale==='bid'?tr('bidding'):tr('fixedPrice'))}</span></div><button class="card-btn main" onclick="document.getElementById('marketSearch').value='${esc((r.brand+' '+r.model).replace(/'/g,"\\'"))}';route('robots');renderListings()">${esc(tr('viewSection'))}</button></article>`);
 const makerCards=makerHits.map(m=>`<article class="search-result-card"><div class="result-type">${esc(tr('searchManufacturers'))}</div><h3>${esc(m.name)}</h3><p>${esc(m.origin)} · ${esc(m.series)}</p><div class="tag-row">${(m.types||[]).slice(0,4).map(x=>`<span>${esc(x)}</span>`).join('')}</div><div class="search-card-actions"><button class="card-btn main" onclick="showMaker('${esc(m.name.replace(/'/g,"\\'"))}')">${esc(tr('explore'))}</button>${m.url?`<a class="card-link" href="${esc(m.url)}" target="_blank" rel="noopener">${esc(tr('openWebsite'))} ↗</a>`:''}</div></article>`);
 const companyCards=companyHits.map(c=>`<article class="search-result-card"><div class="result-type">${esc(tr('searchCompanies'))}</div><h3>${esc(c.name)}</h3><p>${esc(c.type)} · ${esc(c.region)} · ${esc(c.country)}</p><div class="tag-row">${(c.skills||c.makers||[]).slice(0,4).map(x=>`<span>${esc(x)}</span>`).join('')}</div><div class="search-card-actions"><button class="card-btn main" onclick="openAuth('company','${esc(c.name.replace(/'/g,"\\'"))}')">${esc(tr('contact'))}</button>${c.source_url?`<a class="card-link" href="${esc(c.source_url)}" target="_blank" rel="noopener">${esc(tr('openWebsite'))} ↗</a>`:''}</div></article>`);
 const buyCards=buyHits.map(p=>`<article class="search-result-card"><div class="result-type">${esc(tr('searchBuy'))}</div><h3>${esc(p.maker)} · ${esc(p.product)}</h3><p>${esc(p.retailer)} · ${esc(p.country)}</p><div class="result-price">${esc(p.price)}</div><a class="store-button" href="${esc(p.url)}" target="_blank" rel="noopener">${esc(tr('visitStore'))} ↗</a></article>`);
 const eventCards=eventHits.map(e=>`<article class="search-result-card"><div class="result-type">${esc(tr('eventSearch'))}</div><h3>${esc(e.name)}</h3><p>${esc(fmtEventDate(e))} · ${esc(e.city)} · ${esc(e.country)}</p><div class="search-card-actions"><a class="card-link" href="${esc(e.url)}" target="_blank" rel="noopener">${esc(tr('officialEventSite'))} ↗</a></div></article>`);
 const categoryCards=categoryHits.map(c=>`<article class="search-result-card"><div class="result-type">${esc(tr('searchCategories'))}</div><h3>${esc(c.names[lang]||c.names.en)}</h3><p>${esc(c.desc[lang]||c.desc.en)}</p><button class="card-btn main" onclick="${c._kind==='app'?`document.getElementById('applicationFilter').value='${esc(c.id)}'`:`document.getElementById('categoryFilter').value='${esc(c.id)}'`};route('robots');renderListings()">${esc(tr('viewSection'))}</button></article>`);
 out.innerHTML= total ? resultGroup(tr('searchRobots'),robotCards,'robots')+resultGroup(tr('searchManufacturers'),makerCards,'makers')+resultGroup(tr('searchCompanies'),companyCards,'companies')+resultGroup(tr('searchBuy'),buyCards,'buy')+resultGroup(tr('eventSearch'),eventCards,'events')+resultGroup(tr('searchCategories'),categoryCards,'categories') : `<div class="search-empty"><h2>${esc(tr('noSearchResults'))}</h2><p>${esc(tr('searchHint'))}</p></div>`;
}
function runGlobalSearch(){const q=(document.getElementById('globalSearch')?.value||document.getElementById('searchPageInput')?.value||'').trim();if(document.getElementById('searchPageInput'))document.getElementById('searchPageInput').value=q;route('searchResults');renderGlobalSearch(q)}
document.getElementById('searchBtn').addEventListener('click',runGlobalSearch);document.getElementById('globalSearch').addEventListener('keydown',e=>{if(e.key==='Enter')runGlobalSearch()});document.getElementById('searchPageBtn')?.addEventListener('click',()=>renderGlobalSearch(document.getElementById('searchPageInput').value));document.getElementById('searchPageInput')?.addEventListener('keydown',e=>{if(e.key==='Enter')renderGlobalSearch(e.currentTarget.value)});

function toast(msg){const t=document.getElementById('toast');t.textContent=msg;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),1900)}
