const storedLang=localStorage.getItem('rqLangV19');const saved=(storedLang&&T[storedLang])?storedLang:'en';document.getElementById('languageSelect').value=saved;document.getElementById('languageSelect').addEventListener('change',e=>applyLang(e.target.value));applyLang(saved);populateEventFilters();renderEvents();if('serviceWorker' in navigator){window.addEventListener('load',()=>navigator.serviceWorker.register('service-worker.js').catch(()=>{}))}

// =========================================================
// v20 — Supabase Tokyo live-data bridge
// Public directory data is loaded from Supabase when available.
// Static v19 seed data remains as a fallback so the site still works offline.
// =========================================================
const RQ_DB_URL = window.RQ_SUPABASE_URL || '';
const RQ_DB_KEY = window.RQ_SUPABASE_PUBLISHABLE_KEY || '';

const RQ_COUNTRY_NAMES = {
  JP:'Japan', KR:'Korea', CN:'China', TW:'Taiwan', HK:'Hong Kong', SG:'Singapore',
  MY:'Malaysia', TH:'Thailand', VN:'Vietnam', ID:'Indonesia', IN:'India', AU:'Australia',
  NZ:'New Zealand', US:'USA', CA:'Canada', MX:'Mexico', DE:'Germany', FR:'France',
  IT:'Italy', ES:'Spain', GB:'United Kingdom', UK:'United Kingdom', DK:'Denmark',
  SE:'Sweden', NO:'Norway', FI:'Finland', NL:'Netherlands', BE:'Belgium', CH:'Switzerland',
  AT:'Austria', PL:'Poland', CZ:'Czechia', SK:'Slovakia', IL:'Israel', AE:'UAE'
};
function rqCountryName(code){return RQ_COUNTRY_NAMES[String(code||'').toUpperCase()]||String(code||'');}
function rqRegionFromCountry(code){
  code=String(code||'').toUpperCase();
  if(code==='JP')return 'Japan'; if(code==='KR')return 'Korea'; if(code==='CN')return 'China'; if(code==='TW')return 'Taiwan';
  if(['DE','FR','IT','ES','GB','UK','DK','SE','NO','FI','NL','BE','CH','AT','PL','CZ','SK'].includes(code))return 'Europe';
  if(['US','CA','MX'].includes(code))return 'North America';
  if(code==='IN')return 'India';
  if(['SG','MY','TH','VN','ID'].includes(code))return 'Southeast Asia';
  if(['IL','AE'].includes(code))return 'Middle East';
  if(['AU','NZ'].includes(code))return 'Australia';
  return rqCountryName(code)||'Global';
}
function rqRobotType(t){
  const m={industrial_robot:'industrial',cobot:'collaborative',collaborative:'collaborative',scara:'scara',delta:'delta',amr:'amr',warehouse_robot:'warehouse',warehouse:'warehouse',mobile_manipulator:'mobile_manipulator',humanoid:'humanoid',quadruped:'quadruped',cleanroom:'cleanroom',service_robot:'service_robot',embodied_ai:'humanoid',rehabilitation_robot:'service_robot'};
  return m[t]||t;
}
const RQ_PERIPHERAL_TYPES=new Set(['eoat','gripper','vacuum_gripper','vacuum','tool_changer','toolchanger','force_torque_sensor','ft','vision','3d_vision','sensor','pneumatics','robotics_ai']);
const RQ_ROBOT_TYPES=new Set(['industrial_robot','cobot','collaborative','scara','delta','amr','warehouse_robot','warehouse','mobile_manipulator','humanoid','quadruped','cleanroom','service_robot','embodied_ai','rehabilitation_robot']);
function rqMakerFromDb(r){
  const raw=Array.isArray(r.manufacturer_types)?r.manufacturer_types:[];
  const types=[...new Set(raw.map(rqRobotType).filter(Boolean))];
  const hasRobot=raw.some(x=>RQ_ROBOT_TYPES.has(x));
  const hasPeripheral=raw.some(x=>RQ_PERIPHERAL_TYPES.has(x));
  return {
    name:r.name,
    origin:rqCountryName(r.country_code),
    region:rqRegionFromCountry(r.country_code),
    types,
    series:r.description||'RoboQuo live directory',
    status:r.verification_status==='verified'?'official-source':'directory',
    url:r.website_url||r.source_url||'',
    _source:'supabase',
    _group:(!hasRobot&&hasPeripheral)?'eoat':'robot'
  };
}
function rqCompanyType(types){
  const t=(Array.isArray(types)&&types[0])||'company';
  const map={robot_manufacturer:'Robot Manufacturer',authorized_dealer:'Authorized Dealer',robot_dealer:'Robot Dealer',used_robot_dealer:'Used Robot Dealer',system_integrator:'System Integrator',eoat_supplier:'EOAT Supplier',vision_supplier:'Vision Supplier',repair_service:'Repair & Service',training:'Training',logistics:'Logistics',online_retailer:'Online Retailer',manufacturer_office:'Manufacturer Office'};
  return map[t]||String(t).replaceAll('_',' ').replace(/\b\w/g,c=>c.toUpperCase());
}
function rqCompanyFromDb(r){
  return {name:r.name,type:rqCompanyType(r.company_types),country:rqCountryName(r.country_code),region:r.city||r.state_region||rqCountryName(r.country_code)||'Global',skills:Array.isArray(r.company_types)?r.company_types.map(x=>String(x).replaceAll('_',' ')):[],status:r.profile_status==='authorized'?'Authorized':r.profile_status==='verified'?'Verified':r.profile_status==='claimed'?'Claimed':'Directory',source_url:r.website_url||r.source_url||'',_source:'supabase'};
}
function rqEventFromDb(r){
  return {name:r.name,start:r.start_date,end:r.end_date||r.start_date,country:rqCountryName(r.country_code),city:r.city||'',venue:r.venue||'',type:Array.isArray(r.event_types)?r.event_types.join(' / '):'',url:r.official_url||r.source_url||'',checked:r.last_checked_at?String(r.last_checked_at).slice(0,10):'',confirmed:['confirmed','scheduled'].includes(r.status),_source:'supabase'};
}
function rqMoney(v,c){if(v===null||v===undefined||v==='')return 'Check seller';try{return new Intl.NumberFormat('en-US',{style:'currency',currency:c||'USD',maximumFractionDigits:0}).format(Number(v));}catch{return `${c||''} ${v}`.trim();}}
function rqPurchaseFromDb(r){
  const maker=(r.manufacturers&&r.manufacturers.name)||'';
  const model=(r.robot_models&&r.robot_models.name)||'';
  const channel=r.channel_type||'online_store';
  return {retailer:r.seller_name,maker,product:model||maker||r.seller_name,country:rqCountryName(r.country_code),mode:channel==='request_quote'?'Request Quote':channel==='dealer'?'Dealer':channel==='official_channel'?'Official Channel':'Buy Online',price:rqMoney(r.price,r.currency),availability:r.availability_text||'Check seller',status:(r.is_authorized||channel==='official_channel')?'Official':'Retailer',note:'Live directory record from RoboQuo database.',checked:r.last_checked_at?String(r.last_checked_at).slice(0,10):'',url:r.product_url,_source:'supabase'};
}
function rqListingFromDb(r){
  const rm=r.robot_models||{};
  return {id:r.id,brand:(r.manufacturers&&r.manufacturers.name)||'',model:rm.name||r.title||'',year:r.manufacture_year||'',payload:rm.payload_kg?`${rm.payload_kg} kg`:'—',country:rqCountryName(r.country_code),location:r.city||r.state_region||rqCountryName(r.country_code),price:r.price||0,sale:r.listing_type==='auction'?'bid':'fixed',cat:Array.isArray(rm.robot_types)&&rm.robot_types.length?rqRobotType(rm.robot_types[0]):'industrial',apps:[],verified:false,_source:'supabase'};
}
async function rqDbGet(path){
  if(!RQ_DB_URL||!RQ_DB_KEY)throw new Error('Supabase configuration missing');
  const res=await fetch(`${RQ_DB_URL}/rest/v1/${path}`,{headers:{apikey:RQ_DB_KEY,Accept:'application/json'}});
  if(!res.ok)throw new Error(`${res.status} ${await res.text()}`);
  return res.json();
}
function rqMergeByName(base,live){
  const liveKeys=new Set(live.map(x=>norm(x.name)));
  return [...live,...base.filter(x=>!liveKeys.has(norm(x.name)))];
}
function rqDbBadge(state,text){
  let el=document.getElementById('rqDbStatus');
  if(!el){
    el=document.createElement('span'); el.id='rqDbStatus'; el.className='rq-db-status';
    const host=document.querySelector('.header-actions'); if(host)host.insertBefore(el,host.firstChild);
  }
  if(el){el.dataset.state=state;el.textContent=text;}
}
async function loadRoboquoLiveDatabase(){
  rqDbBadge('loading','Tokyo DB…');
  const jobs={
    makers:rqDbGet('manufacturers?select=*&is_active=eq.true&order=name.asc'),
    companies:rqDbGet('companies?select=*&is_public=eq.true&order=name.asc'),
    events:rqDbGet('events?select=*&is_public=eq.true&order=start_date.asc'),
    purchases:rqDbGet('purchase_channels?select=*,manufacturers(name),robot_models(name)&is_active=eq.true'),
    listings:rqDbGet('listings?select=*,manufacturers(name),robot_models(name,payload_kg,robot_types)&status=eq.published&order=published_at.desc')
  };
  const entries=Object.entries(jobs);
  const settled=await Promise.allSettled(entries.map(x=>x[1]));
  let successful=0;
  settled.forEach((result,i)=>{
    const key=entries[i][0];
    if(result.status!=='fulfilled'){console.warn('RoboQuo DB:',key,result.reason);return;}
    successful++;
    const rows=result.value||[];
    if(key==='makers'&&rows.length){
      const mapped=rows.map(rqMakerFromDb);const liveRobot=mapped.filter(x=>x._group==='robot');const liveEoat=mapped.filter(x=>x._group==='eoat');
      makers.robot.splice(0,makers.robot.length,...rqMergeByName(makers.robot,liveRobot));
      makers.eoat.splice(0,makers.eoat.length,...rqMergeByName(makers.eoat,liveEoat));
    }
    if(key==='companies'&&rows.length){companies.splice(0,companies.length,...rqMergeByName(companies,rows.map(rqCompanyFromDb)));}
    if(key==='events'&&rows.length){const live=rows.map(rqEventFromDb);const keys=new Set(live.map(x=>norm(x.name)));events.splice(0,events.length,...live,...events.filter(x=>!keys.has(norm(x.name))));}
    if(key==='purchases'&&rows.length){const live=rows.map(rqPurchaseFromDb);const keys=new Set(live.map(x=>norm(`${x.retailer}|${x.product}`)));purchaseChannels.splice(0,purchaseChannels.length,...live,...purchaseChannels.filter(x=>!keys.has(norm(`${x.retailer}|${x.product}`))));}
    if(key==='listings'&&rows.length){const live=rows.map(rqListingFromDb);const ids=new Set(live.map(x=>String(x.id)));listings.splice(0,listings.length,...live,...listings.filter(x=>!ids.has(String(x.id))));}
  });
  populateCompanyCountries();populateEventFilters();renderCategories();renderListings();renderMakers();renderNetwork();renderPurchaseChannels();renderEvents();
  if(document.getElementById('searchPageInput')?.value)renderGlobalSearch(document.getElementById('searchPageInput').value);
  rqDbBadge(successful?'live':'error',successful?`● Tokyo DB LIVE`:'DB fallback');
  console.info(`RoboQuo v20: ${successful}/${entries.length} live Supabase data sources connected.`);
}
loadRoboquoLiveDatabase().catch(err=>{console.warn('RoboQuo live DB unavailable; using static fallback.',err);rqDbBadge('error','DB fallback');});

